import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"小過","description":"周易集解 - 小過","frontmatter":{"title":"小過","description":"周易集解 - 小過"},"headers":[],"relativePath":"zh/classics/jijie/062.md","filePath":"zh/classics/jijie/062.md"}'),l={name:"zh/classics/jijie/062.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="小過" tabindex="-1">小過 <a class="header-anchor" href="#小過" aria-label="Permalink to “小過”">​</a></h1><h2 id="小過-1" tabindex="-1">小過 <a class="header-anchor" href="#小過-1" aria-label="Permalink to “小過”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>小過，亨，利貞。可小事，不可大事。飛鳥遺之音，不宜上，宜下，大吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>虞翻曰：晉上之三。當從四陰二陽，臨觀之例。臨陽未至三，而觀四已消也。又有飛鳥之象，故知從晉來。杵臼之利，蓋取諸此。柔得中而應乾剛，故亨。五失正，故利貞。過以利貞，與時行也。</p><p>虞翻曰：小謂五。晉坤為事。柔得中。故可小事也。</p><p>虞翻曰：大事，四。剛失位而不中。故不可大事也。</p><p>虞翻曰：離為飛鳥，震為音，艮為止。晉上之三，離去震在，鳥飛而音止。故飛鳥遺之音。上陰乘陽，故不宜上。下陰順陽，故宜下，大吉。俗說或以卦象二陽在內，四陰在外，有似飛鳥之象，妄矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：小過，小者過而亨也。過以利貞，與時行也。柔得中，是以小事吉也。剛失位而不中，是以不可大事也。有飛鳥之象焉，飛鳥遺之音。不宜上，宜下，大吉。上逆而下順也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>荀爽曰：陰稱小。謂四應初，過二而去。三應上，過五而去。五處中，見過不見應。故曰小者過而亨也。</p><p>虞翻曰：謂五也。陰稱小，故小事吉也。</p><p>虞翻曰：謂四也。陽稱大，故不可大事也。</p><p>宋衷曰：二陽在內，上下各陰，有似飛鳥舒翮之象，故曰飛鳥。震為聲音，飛而且鳴，鳥去而音止，故曰遺之音也。</p><p>王肅曰：四、五失位，故曰上逆。二、三得正，故曰下順也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山上有雷，小過。君子以行過乎恭，喪過乎哀，用過乎儉。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：山大而雷小，山上有雷，小過於大，故曰小過。</p><p>虞翻曰：君子，謂三也。上貴三賤，晉上之三，震為行，故行過乎恭。謂三致恭以順存其位，與謙三同義。</p><p>虞翻曰：晉坤為喪，離為目，艮為鼻，坎為涕洟。震為出，涕洟出鼻目，體大過，遭死喪，過乎哀也。</p><p>虞翻曰：坤為財用，為吝嗇。艮為止，兌為小。小用止，密雲不雨，故用過乎儉也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，飛鳥以凶。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：應四。離為飛鳥。上之三，則四折入，大過死，故飛鳥以凶。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：飛鳥以凶，不可如何也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：四死大過，故不可如何也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，過其祖，遇其妣，不及其君，遇其臣，無咎。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：祖謂祖母，初也。母死稱妣。謂三坤為喪，為母，折入大過死，故稱祖也。妣二過初，故過其祖。五變，三體姤遇，故遇妣也。</p><p>虞翻曰：五動為君，晉坎為臣；二之五隔三；艮為止，故不及其君，止如。承三得正，體姤遇象，故遇其臣，無咎也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不及其君，臣不可過也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：體大過，下止舍，巽下，故不可過。與隨三同義。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，弗過防之，從或戕之，凶。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：防，防四也。失位從或而欲折之初。戕，殺也。離為戈兵，三從離上入坤，折四死大過中，故從或戕之，凶也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：從或戕之，凶如何也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：三來戕四，故凶如何也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，無咎，弗過遇之，往厲必戒，勿用永貞。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>《九家易》曰：以陽居陰，行過乎恭。今雖失位，進則遇五，故無咎也。四體震動，位既不正，當動上居五，不復過五，故曰弗過遇之矣。</p><p>荀爽曰：四往危五，戒備於三，故曰往厲必戒也。勿長居四，當動上五，故用永貞。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：弗過遇之，位不當也。往厲必戒，終不可長也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：體否上傾，故終不可長矣。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，密雲不雨，自我西郊。公弋取彼在穴。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：密，小也。晉坎，在天為雲，墜地成雨。上來之三，折坎入兌，小為密。坤為自我。兌為西。五動乾為郊。故密雲不雨，自我西郊也。</p><p>虞翻曰：公謂三也。弋，矰繳射也。坎為弓彈。離為鳥矢。弋無矢也，巽繩連鳥，弋人鳥之象。艮為手，二為穴，手入穴中，故公弋取彼在穴也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：密雲不雨，已上也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：謂三坎水，已之上六，故已上也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，弗遇過之，飛鳥離之，凶，是謂災眚。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：謂四已變之坤，上得之三，故弗遇過之。離為飛鳥，公弋得之，鳥下入艮手而死，故飛鳥離之凶。晉坎為災眚，故是謂災眚矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：弗遇過之，已亢也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：飛下稱亢。晉上之三，故已亢也。</p>',75)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
